// AUTOGENERATED. DO NOT MODIFY.
// To modify this file, run: node scripts/m3/gen-keyboard-tests.mjs list
// Spec: m3.material.io 2026-10-13_06-10-19, lists "Keyboard navigation"
//
// Each case presses real keys and checks the behavior the spec's keyboard
// table lists for that key. `xit` cases are known differences from the spec.

// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-list.js';
import './md-gb-list-item.js';
import {type ListItemElement} from './list-item-element.js';

interface SetupOptions {
  /** Index of the item to render selected. */
  selected?: number;
  /** Value step (sliders). */
  step?: number;
}

interface Fixture {
  root: HTMLElement;
  items: HTMLElement[];
  before: HTMLElement;
  after: HTMLElement;
  /** Indices of the items that received a click (activation). */
  activated: number[];
  // Menus.
  invoker?: HTMLElement;
  menu?: HTMLElement;
  submenu?: HTMLElement;
  submenuItems?: HTMLElement[];
}

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

function fixture(root: HTMLElement, items: HTMLElement[]): Fixture {
  const activated: number[] = [];
  items.forEach((item, i) => {
    item.addEventListener('click', (event) => {
      // Clicks bubbling from nested items (submenus) are not this item's.
      const path = event.composedPath();
      if (path.find((el) => items.includes(el as HTMLElement)) === item) {
        activated.push(i);
      }
    });
  });
  return {
    root,
    items,
    activated,
    before: root.querySelector<HTMLElement>('#before')!,
    after: root.querySelector<HTMLElement>('#after')!,
  };
}

/** Waits for Lit updates, a frame and pending timeouts. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  // Twice: popover toggle events, and the timeouts they start, can land
  // after the next frame.
  for (let i = 0; i < 2; i++) {
    await new Promise((resolve) => requestAnimationFrame(resolve));
    await new Promise((resolve) => setTimeout(resolve));
  }
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

/** The focused element and the focused elements of its shadow roots. */
function focusPath() {
  const path: Element[] = [];
  let el = document.activeElement;
  while (el) {
    path.push(el);
    el = el.shadowRoot?.activeElement ?? null;
  }
  return path;
}

function isFocused(target: Element) {
  return focusPath().includes(target);
}

/** The index of the item that holds focus, or -1. */
function focusedIndex(items: Element[]) {
  const path = focusPath();
  return items.findIndex((item) =>
    path.some((el) => el === item || item.contains(el)),
  );
}

/** Focuses item `index` (negative counts from the end). */
async function focusItem(f: Fixture, index: number) {
  f.items[(index + f.items.length) % f.items.length].focus();
  await settle();
}

async function setup(opts: SetupOptions = {}): Promise<Fixture> {
  const root = await mount(html`
    <button id="before">Before</button>
    <md-gb-list selectable aria-label="Fruits">
      ${['Apples', 'Bananas', 'Cherries'].map(
        (label, i) =>
          html`<md-gb-list-item ?checked=${opts.selected === i}
            >${label}</md-gb-list-item
          >`,
      )}
    </md-gb-list>
    <button id="after">After</button>
  `);
  return fixture(root, [
    ...root.querySelectorAll<HTMLElement>('md-gb-list-item'),
  ]);
}

function selectedIndices(f: Fixture) {
  return f.items.flatMap((item, i) =>
    (item as ListItemElement).checked ? [i] : [],
  );
}

describe('<md-gb-list> keyboard (spec)', () => {
  afterEach(() => {
    container?.remove();
    container = undefined;
  });

  // Spec: "Tab" | "To move focus to the first list item, last list item, or outside of the list component"
  // spec: lists-037464, lists-8101e0
  describe("Tab: To move focus to the first list item, last list item, or outside of the list component", () => {
    it("Tab moves focus to the first item", async () => {
      const f = await setup();
      f.before.focus();
      await press('Tab');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("Shift+Tab moves focus to the last item", async () => {
      const f = await setup();
      f.after.focus();
      await press('Shift+Tab');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    });

    it("Tab from an item moves focus outside the component", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('Tab');
      expect(isFocused(f.after)).toBeTrue();
    });
  });

  // Spec: "Down and right arrow keys" | "Moves to the next element in the list; if the focused element is the last in the list, it wraps back to the top of the list"
  // spec: lists-fe7791, lists-0a0ebe
  describe("Down and right arrow keys: Moves to the next element in the list; if the focused element is the last in the list, it wraps back to the top of the list", () => {
    it("ArrowDown moves focus to the next item", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowDown');
      expect(focusedIndex(f.items)).toBe(1);
    });

    it("ArrowDown wraps from the last item to the first", async () => {
      const f = await setup();
      await focusItem(f, -1);
      await press('ArrowDown');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("ArrowRight moves focus to the next item", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowRight');
      expect(focusedIndex(f.items)).toBe(1);
    });

    it("ArrowRight wraps from the last item to the first", async () => {
      const f = await setup();
      await focusItem(f, -1);
      await press('ArrowRight');
      expect(focusedIndex(f.items)).toBe(0);
    });
  });

  // Spec: "Up and left arrow keys" | "Moves to the previous element in the list; if the focused element is the first in the list, it wraps back to the bottom of the list"
  // spec: lists-68469c, lists-1f3630
  describe("Up and left arrow keys: Moves to the previous element in the list; if the focused element is the first in the list, it wraps back to the bottom of the list", () => {
    it("ArrowUp moves focus to the previous item", async () => {
      const f = await setup();
      await focusItem(f, 1);
      await press('ArrowUp');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("ArrowUp wraps from the first item to the last", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowUp');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    });

    it("ArrowLeft moves focus to the previous item", async () => {
      const f = await setup();
      await focusItem(f, 1);
      await press('ArrowLeft');
      expect(focusedIndex(f.items)).toBe(0);
    });

    it("ArrowLeft wraps from the first item to the last", async () => {
      const f = await setup();
      await focusItem(f, 0);
      await press('ArrowLeft');
      expect(focusedIndex(f.items)).toBe(f.items.length - 1);
    });
  });

  // Spec: "Space or Enter" | "To select a list item not yet selected"
  // spec: lists-d045c4, lists-7773ef
  describe("Space or Enter: To select a list item not yet selected", () => {
    it("Space selects the focused item", async () => {
      const f = await setup({selected:0});
      await focusItem(f, 1);
      await press('Space');
      expect(selectedIndices(f)).toContain(1);
    });

    it("Enter selects the focused item", async () => {
      const f = await setup({selected:0});
      await focusItem(f, 1);
      await press('Enter');
      expect(selectedIndices(f)).toContain(1);
    });
  });
});
